package io.invenlio.receiving;
import io.invenlio.inventory.InventoryPosting;import io.invenlio.organization.*;import io.invenlio.procurement.PurchaseOrderAccess;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.time.*;import java.util.*;import java.util.stream.Collectors;import org.springframework.context.ApplicationEventPublisher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ReceivingService{private static final Set<String> STORAGE=Set.of("AISLE","RACK","SHELF","BIN","FLOOR","PALLET_POSITION");private final AuthorizationService auth;private final AuditTrail audit;private final PurchaseOrderAccess orders;private final WarehouseAvailability warehouses;private final InventoryPosting inventory;private final JdbcTemplate db;private final ApplicationEventPublisher events;ReceivingService(AuthorizationService a,AuditTrail au,PurchaseOrderAccess o,WarehouseAvailability w,InventoryPosting i,JdbcTemplate d,ApplicationEventPublisher e){auth=a;audit=au;orders=o;warehouses=w;inventory=i;db=d;events=e;}
 @Transactional Receipt create(Create c){var a=auth.require(Permission.RECEIVING_MANAGE);var po=orders.findReceivable(a.tenantId(),required(c.purchaseOrderId,"purchaseOrderId")).orElseThrow(()->err("PURCHASE_ORDER_NOT_RECEIVABLE","Purchase order is inaccessible or not receiving eligible"));if(c.lines==null||c.lines.isEmpty())throw err("RECEIPT_LINES_REQUIRED","At least one receipt line is required");int year=Year.now(ZoneOffset.UTC).getValue();long seq=db.queryForObject("INSERT INTO goods_receipt_number_counters(tenant_id,receipt_year,next_value) VALUES(?,?,2) ON CONFLICT(tenant_id,receipt_year) DO UPDATE SET next_value=goods_receipt_number_counters.next_value+1 RETURNING next_value-1",Long.class,a.tenantId(),year);UUID id=UUID.randomUUID();String number="GR-"+year+"-"+String.format("%06d",seq);db.update("INSERT INTO goods_receipts(id,tenant_id,purchase_order_id,supplier_id,warehouse_id,receipt_number,status,note,created_by,created_at,updated_at,version) VALUES(?,?,?,?,?,?,'DRAFT',?,?,now(),now(),0)",id,a.tenantId(),po.purchaseOrderId(),po.supplierId(),po.warehouseId(),number,text(c.note,1000),a.userId());Set<UUID> serials=new HashSet<>();for(Line command:c.lines){var line=po.lines().stream().filter(x->x.lineId().equals(command.purchaseOrderLineId)).findFirst().orElseThrow(()->err("PURCHASE_ORDER_LINE_NOT_FOUND","PO line is inaccessible or mismatched"));BigDecimal q=quantity(command.receivedBaseQuantity);if(q.compareTo(line.remainingBaseQuantity())>0)throw err("PURCHASE_ORDER_OVER_RECEIPT","Receipt exceeds line remaining quantity");var location=warehouses.findUsableLocation(a.tenantId(),po.warehouseId(),command.receivingLocationId).orElseThrow(()->err("RECEIVING_LOCATION_INVALID","Location is inaccessible, inactive or belongs to another warehouse"));if(!location.type().equals("RECEIVING"))throw err("RECEIVING_LOCATION_REQUIRED","Goods must enter through a receiving location");if(command.serialId!=null&&!serials.add(command.serialId))throw err("DUPLICATE_SERIAL","Serial may occur only once per receipt");db.update("INSERT INTO goods_receipt_lines(id,tenant_id,goods_receipt_id,purchase_order_id,purchase_order_line_id,variant_id,warehouse_id,receiving_location_id,received_base_quantity,unit_code,lot_id,serial_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,now(),now())",UUID.randomUUID(),a.tenantId(),id,po.purchaseOrderId(),line.lineId(),line.variantId(),po.warehouseId(),command.receivingLocationId,q,line.baseUnit(),command.lotId,command.serialId);}audit.record(a,"GOODS_RECEIPT_CREATED","goods-receipt",id.toString());return receipt(a.tenantId(),id);}
 @Transactional Receipt post(UUID id,String key,long version){var a=auth.require(Permission.RECEIVING_MANAGE);key(key);lock(a.tenantId()+":receipt-post:"+key);var keyed=db.query("SELECT id,post_fingerprint FROM goods_receipts WHERE tenant_id=? AND post_idempotency_key=?",(r,n)->Map.entry((UUID)r.getObject(1),r.getString(2)),a.tenantId(),key);String fp=hash(id+"|"+version);if(!keyed.isEmpty()){if(!keyed.getFirst().getKey().equals(id)||!keyed.getFirst().getValue().equals(fp))throw err("IDEMPOTENCY_KEY_REUSED","Idempotency key was used for a different receipt request");return receipt(a.tenantId(),id);}Receipt r=lockReceipt(a.tenantId(),id);if(!r.status.equals("DRAFT")||r.version!=version)throw err("CONCURRENT_MODIFICATION","Receipt is not draft or version is stale");var stocks=r.lines.stream().map(l->new InventoryPosting.Stock(l.variantId,r.warehouseId,l.receivingLocationId,l.lotId,l.serialId,l.receivedBaseQuantity)).toList();try{inventory.receive(a.tenantId(),a.subject(),"goods-receipt:"+id,stocks);Map<UUID,BigDecimal> totals=r.lines.stream().collect(Collectors.toMap(LineView::purchaseOrderLineId,LineView::receivedBaseQuantity,BigDecimal::add));orders.recordReceipt(a.tenantId(),r.purchaseOrderId,totals);}catch(RuntimeException e){throw translate(e);}int n=db.update("UPDATE goods_receipts SET status='POSTED',received_at=now(),received_by=?,post_idempotency_key=?,post_fingerprint=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='DRAFT' AND version=?",a.userId(),key,fp,a.tenantId(),id,version);if(n!=1)throw err("CONCURRENT_MODIFICATION","Receipt posting raced with another request");audit.record(a,"GOODS_RECEIPT_POSTED","goods-receipt",id.toString());events.publishEvent(new ReceivingEvents.GoodsReceiptPosted(a.tenantId(),id,r.purchaseOrderId));return receipt(a.tenantId(),id);}
 @Transactional Task createTask(TaskCreate c){var a=auth.require(Permission.PUT_AWAY_MANAGE);var rows=db.query("SELECT l.goods_receipt_id,l.variant_id,l.warehouse_id,l.receiving_location_id,l.lot_id,l.serial_id,l.received_base_quantity,l.unit_code FROM goods_receipt_lines l JOIN goods_receipts r ON r.tenant_id=l.tenant_id AND r.id=l.goods_receipt_id WHERE l.tenant_id=? AND l.id=? AND r.status='POSTED' FOR UPDATE OF l",(x,n)->new Source((UUID)x.getObject(1),(UUID)x.getObject(2),(UUID)x.getObject(3),(UUID)x.getObject(4),(UUID)x.getObject(5),(UUID)x.getObject(6),x.getBigDecimal(7),x.getString(8)),a.tenantId(),c.receiptLineId);if(rows.isEmpty())throw err("RECEIPT_LINE_NOT_FOUND","Posted receipt line not found");Source s=rows.getFirst();var destination=warehouses.findUsableLocation(a.tenantId(),s.warehouseId,c.destinationLocationId).orElseThrow(()->err("DESTINATION_LOCATION_INVALID","Destination is inaccessible, inactive or in another warehouse"));if(!STORAGE.contains(destination.type()))throw err("DESTINATION_NOT_STORAGE_ELIGIBLE","Destination is not storage eligible");BigDecimal q=quantity(c.quantity);BigDecimal allocated=db.queryForObject("SELECT COALESCE(sum(quantity),0) FROM put_away_tasks WHERE tenant_id=? AND goods_receipt_line_id=?",BigDecimal.class,a.tenantId(),c.receiptLineId);if(allocated.add(q).compareTo(s.quantity)>0)throw err("PUT_AWAY_QUANTITY_EXCEEDED","Put-away exceeds receipt line quantity");UUID id=UUID.randomUUID();db.update("INSERT INTO put_away_tasks(id,tenant_id,goods_receipt_id,goods_receipt_line_id,variant_id,warehouse_id,source_location_id,destination_location_id,lot_id,serial_id,quantity,unit_code,status,created_by,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'PENDING',?,now(),now(),0)",id,a.tenantId(),s.receiptId,c.receiptLineId,s.variantId,s.warehouseId,s.locationId,c.destinationLocationId,s.lotId,s.serialId,q,s.unit,a.userId());audit.record(a,"PUT_AWAY_CREATED","put-away-task",id.toString());return task(a.tenantId(),id);}
 @Transactional Task complete(UUID id,String key,long version){var a=auth.require(Permission.PUT_AWAY_MANAGE);key(key);lock(a.tenantId()+":putaway-complete:"+key);var keyed=db.query("SELECT id,completion_fingerprint FROM put_away_tasks WHERE tenant_id=? AND completion_idempotency_key=?",(r,n)->Map.entry((UUID)r.getObject(1),r.getString(2)),a.tenantId(),key);String fp=hash(id+"|"+version);if(!keyed.isEmpty()){if(!keyed.getFirst().getKey().equals(id)||!keyed.getFirst().getValue().equals(fp))throw err("IDEMPOTENCY_KEY_REUSED","Idempotency key was used for another put-away");return task(a.tenantId(),id);}Task t=lockTask(a.tenantId(),id);if(!t.status.equals("PENDING")||t.version!=version)throw err("CONCURRENT_MODIFICATION","Put-away is complete or version is stale");try{inventory.relocate(a.tenantId(),a.subject(),"put-away:"+id,new InventoryPosting.Stock(t.variantId,t.warehouseId,t.sourceLocationId,t.lotId,t.serialId,t.quantity),t.destinationLocationId);}catch(RuntimeException e){throw translate(e);}if(db.update("UPDATE put_away_tasks SET status='COMPLETED',completed_at=now(),completed_by=?,completion_idempotency_key=?,completion_fingerprint=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='PENDING' AND version=?",a.userId(),key,fp,a.tenantId(),id,version)!=1)throw err("CONCURRENT_MODIFICATION","Put-away completion raced");audit.record(a,"PUT_AWAY_COMPLETED","put-away-task",id.toString());events.publishEvent(new ReceivingEvents.PutAwayCompleted(a.tenantId(),id,t.receiptId));return task(a.tenantId(),id);}
 @Transactional(readOnly=true)Receipt get(UUID id){var a=auth.require(Permission.RECEIVING_READ);return receipt(a.tenantId(),id);}@Transactional(readOnly=true)List<Receipt> list(String number,UUID po,UUID supplier,UUID warehouse,String status,LocalDate from,LocalDate to,int page,int size,String sort){var a=auth.require(Permission.RECEIVING_READ);bounds(page,size);String order=sort(sort,Map.of("createdAt","created_at","receiptNumber","receipt_number","receivedAt","received_at","status","status"),"created_at DESC");return db.query("SELECT id FROM goods_receipts WHERE tenant_id=? AND (?::text IS NULL OR receipt_number=?::text) AND (?::uuid IS NULL OR purchase_order_id=?::uuid) AND (?::uuid IS NULL OR supplier_id=?::uuid) AND (?::uuid IS NULL OR warehouse_id=?::uuid) AND (?::text IS NULL OR status=?::text) AND (?::date IS NULL OR created_at::date>=?::date) AND (?::date IS NULL OR created_at::date<=?::date) ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->receipt(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),number,number,po,po,supplier,supplier,warehouse,warehouse,status,status,from,from,to,to,page*size,size);}@Transactional(readOnly=true)Task getTask(UUID id){var a=auth.require(Permission.PUT_AWAY_READ);return task(a.tenantId(),id);}@Transactional(readOnly=true)List<Task> tasks(UUID receipt,UUID warehouse,UUID source,UUID destination,String status,int page,int size){var a=auth.require(Permission.PUT_AWAY_READ);bounds(page,size);return db.query("SELECT id FROM put_away_tasks WHERE tenant_id=? AND (?::uuid IS NULL OR goods_receipt_id=?::uuid) AND (?::uuid IS NULL OR warehouse_id=?::uuid) AND (?::uuid IS NULL OR source_location_id=?::uuid) AND (?::uuid IS NULL OR destination_location_id=?::uuid) AND (?::text IS NULL OR status=?::text) ORDER BY created_at DESC,id OFFSET ? LIMIT ?",(r,n)->task(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),receipt,receipt,warehouse,warehouse,source,source,destination,destination,status,status,page*size,size);}
 private Receipt receipt(UUID tenant,UUID id){var x=db.query("SELECT id,receipt_number,purchase_order_id,supplier_id,warehouse_id,status,received_at,received_by,note,created_at,updated_at,version FROM goods_receipts WHERE tenant_id=? AND id=?",(r,n)->new Receipt((UUID)r.getObject(1),r.getString(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),r.getString(6),instant(r.getTimestamp(7)),(UUID)r.getObject(8),r.getString(9),r.getTimestamp(10).toInstant(),r.getTimestamp(11).toInstant(),r.getLong(12),lines(tenant,id)),tenant,id);if(x.isEmpty())throw err("GOODS_RECEIPT_NOT_FOUND","Goods receipt not found");return x.getFirst();}private Receipt lockReceipt(UUID t,UUID id){db.query("SELECT id FROM goods_receipts WHERE tenant_id=? AND id=? FOR UPDATE",(r,n)->r.getObject(1),t,id);return receipt(t,id);}private List<LineView> lines(UUID t,UUID id){return db.query("SELECT id,purchase_order_line_id,variant_id,receiving_location_id,received_base_quantity,unit_code,lot_id,serial_id FROM goods_receipt_lines WHERE tenant_id=? AND goods_receipt_id=? ORDER BY created_at,id",(r,n)->new LineView((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),r.getBigDecimal(5),r.getString(6),(UUID)r.getObject(7),(UUID)r.getObject(8)),t,id);}private Task task(UUID t,UUID id){var x=db.query("SELECT id,goods_receipt_id,goods_receipt_line_id,variant_id,warehouse_id,source_location_id,destination_location_id,lot_id,serial_id,quantity,unit_code,status,completed_at,created_at,updated_at,version FROM put_away_tasks WHERE tenant_id=? AND id=?",(r,n)->new Task((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),(UUID)r.getObject(6),(UUID)r.getObject(7),(UUID)r.getObject(8),(UUID)r.getObject(9),r.getBigDecimal(10),r.getString(11),r.getString(12),instant(r.getTimestamp(13)),r.getTimestamp(14).toInstant(),r.getTimestamp(15).toInstant(),r.getLong(16)),t,id);if(x.isEmpty())throw err("PUT_AWAY_NOT_FOUND","Put-away task not found");return x.getFirst();}private Task lockTask(UUID t,UUID id){db.query("SELECT id FROM put_away_tasks WHERE tenant_id=? AND id=? FOR UPDATE",(r,n)->r.getObject(1),t,id);return task(t,id);}
 private void lock(String v){db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,v);}private static BigDecimal quantity(String raw){try{BigDecimal q=new BigDecimal(raw).setScale(6,RoundingMode.UNNECESSARY);if(q.signum()<=0||q.precision()>19)throw new Exception();return q;}catch(Exception e){throw err("INVALID_QUANTITY","Positive exact NUMERIC(19,6) quantity required");}}private static void key(String k){if(k==null||k.isBlank()||k.length()>128)throw err("IDEMPOTENCY_KEY_REQUIRED","A valid Idempotency-Key is required");}private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static ReceivingException translate(RuntimeException e){String m=e.getMessage()==null?"Receiving operation failed":e.getMessage();String code=m.toUpperCase().replace(' ','_');if(code.length()>80)code="RECEIVING_OPERATION_FAILED";return err(code,m);}private static void bounds(int p,int s){if(p<0||s<1||s>100)throw err("INVALID_PAGINATION","Invalid pagination");}private static String sort(String v,Map<String,String>a,String d){if(v==null||v.isBlank())return d;String[] p=v.split(",",-1);if(p.length>2||!a.containsKey(p[0])||(p.length==2&&!Set.of("asc","desc").contains(p[1].toLowerCase())))throw err("INVALID_SORT","Unsupported sort");return a.get(p[0])+" "+(p.length==2?p[1]:"asc");}private static String text(String s,int n){if(s==null)return null;s=s.trim();if(s.length()>n)throw err("INVALID_RECEIPT_DATA","Value too long");return s.isBlank()?null:s;}private static <T>T required(T x,String name){if(x==null)throw err("INVALID_RECEIPT_DATA",name+" is required");return x;}private static Instant instant(Timestamp t){return t==null?null:t.toInstant();}private static ReceivingException err(String c,String m){return new ReceivingException(c,m);}
 record Create(UUID purchaseOrderId,String note,List<Line> lines){}record Line(UUID purchaseOrderLineId,String receivedBaseQuantity,UUID receivingLocationId,UUID lotId,UUID serialId){}record TaskCreate(UUID receiptLineId,UUID destinationLocationId,String quantity){}record Receipt(UUID id,String receiptNumber,UUID purchaseOrderId,UUID supplierId,UUID warehouseId,String status,Instant receivedAt,UUID receivedBy,String note,Instant createdAt,Instant updatedAt,long version,List<LineView> lines){}record LineView(UUID id,UUID purchaseOrderLineId,UUID variantId,UUID receivingLocationId,BigDecimal receivedBaseQuantity,String unitCode,UUID lotId,UUID serialId){}record Task(UUID id,UUID receiptId,UUID receiptLineId,UUID variantId,UUID warehouseId,UUID sourceLocationId,UUID destinationLocationId,UUID lotId,UUID serialId,BigDecimal quantity,String unitCode,String status,Instant completedAt,Instant createdAt,Instant updatedAt,long version){}private record Source(UUID receiptId,UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,BigDecimal quantity,String unit){}
}
